            return False
        body = {field: record[field] for field in STEP_FIELDS}
        if _digest_body(body) != record["sha256"]:
            return False
        previous = record["sha256"]

    # The input summary is the input of the first executed record.
    if steps[0]["input_sha256"] != summary["sha256"]:
        return False
    return manifest["final_sha256"] == previous

